package com.example.lms.service;
import com.example.lms.dto.*; import com.example.lms.entity.*; import com.example.lms.exception.*; import com.example.lms.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.List;
@Service public class BorrowRecordService {private final BorrowRecordRepository records;private final BookRepository books;private final StudentProfileRepository students;public BorrowRecordService(BorrowRecordRepository r,BookRepository b,StudentProfileRepository s){records=r;books=b;students=s;}@Transactional(readOnly=true) public List<BorrowRecordResponse> list(String status){var source="BORROWED".equalsIgnoreCase(status)?records.findByReturnDateIsNull():"RETURNED".equalsIgnoreCase(status)?records.findByReturnDateIsNotNull():records.findAll();return source.stream().map(this::response).toList();}@Transactional public BorrowRecordResponse borrow(BorrowRequest r){var book=books.findById(r.bookId()).orElseThrow(()->new ResourceNotFoundException("Book %d was not found.".formatted(r.bookId())));if(!book.isAvailable())throw new BusinessRuleException("BOOK_UNAVAILABLE","The selected book is not available for borrowing.");var student=students.findById(r.studentId()).orElseThrow(()->new ResourceNotFoundException("Student %d was not found.".formatted(r.studentId())));var record=new BorrowRecord();record.setBook(book);record.setStudent(student);record.setBorrowerName(student.getName());record.setBorrowerEmail(student.getEmail());record.setBorrowerPhone(student.getPhone());record.setBorrowDate(r.borrowDate());book.setAvailable(false);return response(records.save(record));}@Transactional public void returnBook(Long id){var record=records.findById(id).orElseThrow(()->new ResourceNotFoundException("Borrow record %d was not found.".formatted(id)));if(record.getReturnDate()!=null)throw new BusinessRuleException("ALREADY_RETURNED","This borrow record has already been returned.");record.setReturnDate(LocalDate.now());record.getBook().setAvailable(true);}private BorrowRecordResponse response(BorrowRecord r){return new BorrowRecordResponse(r.getId(),r.getBook().getId(),r.getBook().getTitle(),r.getStudent().getId(),r.getBorrowerName(),r.getBorrowerEmail(),r.getBorrowerPhone(),r.getBorrowDate(),r.getReturnDate(),r.getReturnDate()==null?"BORROWED":"RETURNED");}}
